    step("64 KiB 的消息(请求和响应各一份)的连接数曲线,64 个并发调用者:1 条连接 21902 请求/秒(约 1369 MiB/秒的请求方向流量,p50 2869 µs、p99 5000 µs);2 条 25793;4 条 28625(p50 1893 µs、p99 7311 µs);8 条 27667;16 条 28424。1 条连接已经能跑到 1369 MiB/秒,增加连接最多再多约三成就到顶,而且 p99 在 8 条时变到 11008 µs——大消息的瓶颈在拷贝和内存带宽,多开连接帮助有限。", t=tl(S(2)), done=lidx(S(2), '16 条连接'), mark=lidx(S(2), ' 1 条连接'), b=bars([['1 条连接 请求/秒', 21902, '21902'], ['4 条', 28625, '28625'], ['16 条', 28424, '28424']], 30000, mark=[0], done=[1, 2]), kv=KV([['1 条连接', '21902 请求/秒,约 1369 MiB/秒'], ['4 条', '28625 请求/秒'], ['p99', '8 条时 11008 µs,更差']], ['p99'])),
    step("一条连接上并发调用者数的曲线(小消息):1 个调用者 12421 请求/秒(p50 79 µs、p99 114 µs);4 个 32715(p50 118 µs);16 个 66541(p50 226 µs);64 个 92493(p50 650 µs、p99 1374 µs);256 个 122073(p50 2090 µs、p99 3351 µs)。并发越高吞吐越大,但延迟也越高:吞吐还在涨时,p50 已经从 79 µs 涨到 2090 µs(排队)。一条连接在这台机器上最多跑到约 12 万请求/秒(256 个并发),但那是用延迟换来的。", t=tl(S(3)), done=lidx(S(3), '256 个并发调用者'), mark=lidx(S(3), '  1 个并发调用者'), b=bars([['1 个调用者 请求/秒', 12421, '12421'], ['16 个', 66541, '66541'], ['256 个', 122073, '122073']], 130000, mark=[0], done=[1, 2]), kv=KV([['1 → 256 个并发', '12421 → 122073 请求/秒'], ['p50 延迟', '79 µs → 2090 µs'], ['含义', '吞吐靠排队换,延迟随并发上升']], ['含义'])),
    step("一个调用者(无并发)的往返:Unary 12059 次/秒(p50 79 µs、p99 169 µs);同一个 Bidi 流上来回 echo 15634 次/秒(p50 62 µs、p99 95 µs)。流式比 Unary 快大约 30%——省掉了每个调用的建流(HEADERS)和结束(trailers)开销,但只对无并发、小消息的往返成立,而且只比较了这一种形态。", t=tl(S(4)), done=lidx(S(4), 'Bidi 流'), mark=lidx(S(4), 'Unary:'), b=bars([['Unary 次/秒', 12059, '12059'], ['Bidi 流 次/秒', 15634, '15634']], 16500, mark=[0], done=[1]), kv=KV([['Unary', 'p50 79 µs'], ['Bidi 流', 'p50 62 µs'], ['差别', '约 30%,来自省掉建流和结束的开销(推断)']], ['差别'])),
